(2457944, 337977, 38032, '<td valign="top">Beautiful child and a great happy face! ... Successful agreed, however the lack of good focus hurts this tremendously.</td>', 'Beautiful child and a great happy face! ... Successful agreed, however the lack of good focus hurts this tremendously.', '2006-05-25 20:53:34.000000', NULL, 1),
(2457950, 338210, 38032, '<td valign="top">I keep looking at the spot (bird?) ... look at the model darn it!   The dress is simply awesome here ... the phallic background is an interesting choice.</td>', 'I keep looking at the spot (bird?) ... look at the model darn it!   The dress is simply awesome here ... the phallic background is an interesting choice.', '2006-05-25 20:54:50.000000', NULL, 1),
