(2460543, 337607, 56673, '<td valign="top">Nice natural posture and smile, excellent color.  Very well done.  And congratulations to the graduate!</td>', 'Nice natural posture and smile, excellent color.  Very well done.  And congratulations to the graduate!', '2006-05-26 17:15:16.000000', NULL, 1),
(2460549, 337517, 56673, '<td valign="top">By any measure a success.  I hope this gets framed and hung in a prominent place in their home.  Very nice.</td>', 'By any measure a success.  I hope this gets framed and hung in a prominent place in their home.  Very nice.', '2006-05-26 17:16:54.000000', NULL, 1),
(2460551, 337278, 56673, '<td valign="top">They sure grow up fast.  They look like great kids.</td>', 'They sure grow up fast.  They look like great kids.', '2006-05-26 17:17:50.000000', NULL, 1),
