(2460560, 338052, 56673, '<td valign="top">Wonderful capture of a big moment.</td>', 'Wonderful capture of a big moment.', '2006-05-26 17:20:28.000000', NULL, 1),
(2460571, 338148, 56673, '<td valign="top">She''s a really beautiful woman. Really.  And I thank her for her service.  I''m a little uneasy about using the uniform this way.  But maybe it would work as a recruiting poster?</td>', 'She''s a really beautiful woman. Really.  And I thank her for her service.  I''m a little uneasy about using the uniform this way.  But maybe it would work as a recruiting poster?', '2006-05-26 17:25:08.000000', NULL, 1),
