(2460660, 336584, 12733, '<td valign="top">Nice idea, and a good rendition - but I''d like to see the builder in the picture.</td>', 'Nice idea, and a good rendition - but I''d like to see the builder in the picture.', '2006-05-26 18:02:38.000000', NULL, 1),
(2460664, 336772, 12733, '<td valign="top">...on the American empire??? I find the flag too dark against the overbright sky - possibly less contrast would help.</td>', '...on the American empire??? I find the flag too dark against the overbright sky - possibly less contrast would help.', '2006-05-26 18:03:51.000000', NULL, 1),
(2460665, 337822, 12733, '<td valign="top">Congratulations - but this doesn''t have much interest as a photograph, at least not for me.</td>', 'Congratulations - but this doesn''t have much interest as a photograph, at least not for me.', '2006-05-26 18:04:19.000000', NULL, 1),
(2460674, 338326, 12733, '<td valign="top">The statue makes a powerful statement. I find the greenish tint kind of comtrived, and the leaves that seem to be growing out of his back weaken the effect.</td>', 'The statue makes a powerful statement. I find the greenish tint kind of comtrived, and the leaves that seem to be growing out of his back weaken the effect.', '2006-05-26 18:07:45.000000', NULL, 1),
