INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2460676, 338198, 12733, '<td valign="top">A picture like this one depends on critical sharpness and a really great arrangement. Your arrangement is nice, but not spectacular and the picture doesn''t seem sharp enough, especially in the foreground.</td>', 'A picture like this one depends on critical sharpness and a really great arrangement. Your arrangement is nice, but not spectacular and the picture doesn''t seem sharp enough, especially in the foreground.', '2006-05-26 18:07:59.000000', NULL, 1),
(2460678, 337163, 12733, '<td valign="top">Ummm ... it''s a very pretty picture, but strawberries on a spruce tree isn''t successful; it''s just weird. I''ll apologize if the strawberries are actually growing on the spruce tree!</td>', 'Ummm ... it''s a very pretty picture, but strawberries on a spruce tree isn''t successful; it''s just weird. I''ll apologize if the strawberries are actually growing on the spruce tree!', '2006-05-26 18:08:16.000000', NULL, 1),
(2460679, 338105, 12733, '<td valign="top">A great expression, but the colors seem way oversaturated. Poker hands, incidentally have five cards.</td>', 'A great expression, but the colors seem way oversaturated. Poker hands, incidentally have five cards.', '2006-05-26 18:08:25.000000', NULL, 1),
(2460681, 338046, 12733, '<td valign="top">Nice idea, using objects to show a wedding, but the overall effect is too busy, and too many items that one normally does not associate with a wedding.</td>', 'Nice idea, using objects to show a wedding, but the overall effect is too busy, and too many items that one normally does not associate with a wedding.', '2006-05-26 18:09:31.000000', NULL, 1),
(2460683, 336589, 12733, '<td valign="top">Congratulations - it must be a great moment, but the picture doesn''t really show it. The blurry background distracts rather than adding meaning.</td>', 'Congratulations - it must be a great moment, but the picture doesn''t really show it. The blurry background distracts rather than adding meaning.', '2006-05-26 18:09:38.000000', NULL, 1),
(2460685, 336632, 12733, '<td valign="top">Great concept, but too busy - the blurry scissors and other tool in the foreground weaken it.</td>', 'Great concept, but too busy - the blurry scissors and other tool in the foreground weaken it.', '2006-05-26 18:10:19.000000', NULL, 1),
(2460686, 338218, 12733, '<td valign="top">Nice idea, but the oversaturated colors - especially the red on the face - doesn''t appeal to me at all. A slight shift in hue would make a great difference.</td>', 'Nice idea, but the oversaturated colors - especially the red on the face - doesn''t appeal to me at all. A slight shift in hue would make a great difference.', '2006-05-26 18:10:27.000000', NULL, 1),
(2460687, 335884, 39484, '<td valign="top">7</td>', '7', '2006-05-26 18:11:03.000000', NULL, 1),
(2460692, 337772, 12733, '<td valign="top">A nice family snapshot, but it doesn''t have the image quality of a high-scoring challenge photo.</td>', 'A nice family snapshot, but it doesn''t have the image quality of a high-scoring challenge photo.', '2006-05-26 18:12:03.000000', NULL, 1),
(2460693, 337824, 12733, '<td valign="top">I like the way the fabric came out; the sink is out of focus, and the pink is especially distracting. It would seem that success will come after the stains are cleaned, not yet.</td>', 'I like the way the fabric came out; the sink is out of focus, and the pink is especially distracting. It would seem that success will come after the stains are cleaned, not yet.', '2006-05-26 18:12:26.000000', NULL, 1),
