(2460699, 336260, 39484, '<td valign="top">Nice concept</td>', 'Nice concept', '2006-05-26 18:13:01.000000', NULL, 1),
(2460702, 338279, 39484, '<td valign="top">This is a great moment.  nice job</td>', 'This is a great moment.  nice job', '2006-05-26 18:15:21.000000', NULL, 1),
(2460710, 338198, 39484, '<td valign="top">nice concept.  Make sure when using the auto focus you focus on areas of high contrast like the edge of the medal.  It sort of looks like your camera caught the white instead.</td>', 'nice concept.  Make sure when using the auto focus you focus on areas of high contrast like the edge of the medal.  It sort of looks like your camera caught the white instead.', '2006-05-26 18:17:41.000000', NULL, 1),
