(2460920, 338334, 30669, '<td valign="top">A winner! Great shot! 10</td>', 'A winner! Great shot! 10', '2006-05-26 19:49:56.000000', NULL, 1),
(2460924, 337014, 3032, '<td valign="top">Fantastic, the dark tones of the hair stand out so well against the other light and middle gray ones.</td>', 'Fantastic, the dark tones of the hair stand out so well against the other light and middle gray ones.', '2006-05-26 19:51:58.000000', NULL, 1),
(2460941, 337168, 3102, '<td valign="top">I think this would have been more effective if the fisherman were isolated in the shot.  The dock, walkway to the dock, object in the water, etc., detract from the shot.</td>', 'I think this would have been more effective if the fisherman were isolated in the shot.  The dock, walkway to the dock, object in the water, etc., detract from the shot.', '2006-05-26 19:58:57.000000', NULL, 1),
