(2460952, 337833, 3032, '<td valign="top">Great photo. It captures a wonderful expression in a great setting. 10</td>', 'Great photo. It captures a wonderful expression in a great setting. 10', '2006-05-26 20:02:56.000000', NULL, 1),
(2460955, 337517, 3102, '<td valign="top">Seems rather snapshot-ish, to be honest.  The people in the background are big distractions here, not to mention that one of the subjects is looking at the camera and the other one looks like he is wishing he was somewhere else.</td>', 'Seems rather snapshot-ish, to be honest.  The people in the background are big distractions here, not to mention that one of the subjects is looking at the camera and the other one looks like he is wishing he was somewhere else.', '2006-05-26 20:04:40.000000', NULL, 1),
(2460956, 338317, 3032, '<td valign="top">Great light, the look of an evil genius. :)</td>', 'Great light, the look of an evil genius. :)', '2006-05-26 20:04:48.000000', NULL, 1),
(2460965, 337014, 3102, '<td valign="top">A really sweet shot.  I wish you hadn''t spoiled it with the giant border, though.</td>', 'A really sweet shot.  I wish you hadn''t spoiled it with the giant border, though.', '2006-05-26 20:07:23.000000', NULL, 1),
(2460968, 337957, 3102, '<td valign="top">A cool shot... too bad it''s so pixelated.  This would have been much better saved at a better .jpg compression ratio.</td>', 'A cool shot... too bad it''s so pixelated.  This would have been much better saved at a better .jpg compression ratio.', '2006-05-26 20:09:14.000000', NULL, 1),
