(2461103, 335854, 56002, '<td valign="top">stark.  excellent</td>', 'stark.  excellent', '2006-05-26 22:04:24.000000', NULL, 1),
(2461107, 337882, 56002, '<td valign="top">Great colors!  Love it.</td>', 'Great colors!  Love it.', '2006-05-26 22:07:13.000000', NULL, 1),
(2461154, 338055, 52675, '<td valign="top">The green background really makes the yellow flowers POP. Nice composition.</td>', 'The green background really makes the yellow flowers POP. Nice composition.', '2006-05-26 22:38:29.000000', NULL, 1),
(2461156, 335795, 52675, '<td valign="top">Beautiful color. Good title.</td>', 'Beautiful color. Good title.', '2006-05-26 22:40:24.000000', NULL, 1),
(2461163, 338332, 52675, '<td valign="top">This is an unusual family photo, but I think it''s wonderful. Really sharp.</td>', 'This is an unusual family photo, but I think it''s wonderful. Really sharp.', '2006-05-26 22:44:07.000000', NULL, 1),
(2461172, 337931, 52675, '<td valign="top">Really brilliant idea and execution.</td>', 'Really brilliant idea and execution.', '2006-05-26 22:53:02.000000', NULL, 1),
(2461259, 337009, 58906, '<td valign="top">Great capture.  I like the moment frozen in time.  A real ''keeper''.  Well done.</td>', 'Great capture.  I like the moment frozen in time.  A real ''keeper''.  Well done.', '2006-05-26 23:51:57.000000', NULL, 1),
(2461265, 338005, 58906, '<td valign="top">Even though taken in sunlight, a fill flash may have lightened the shadows on the faces of the subjects wearing hats.  Nice catch and nice capture.</td>', 'Even though taken in sunlight, a fill flash may have lightened the shadows on the faces of the subjects wearing hats.  Nice catch and nice capture.', '2006-05-26 23:54:56.000000', NULL, 1),
(2461275, 337938, 58906, '<td valign="top">Bright, colorful, and sharply focused. Well done.</td>', 'Bright, colorful, and sharply focused. Well done.', '2006-05-26 23:58:14.000000', NULL, 1),
(2461286, 338137, 58906, '<td valign="top">Congratulations!  What a head of hair!  Adorable baby and a sweet pose.  May have added interest and impact to the image taken from a lower angle like right above the crib sheet rather than the standard ''adult'' perspective.</td>', 'Congratulations!  What a head of hair!  Adorable baby and a sweet pose.  May have added interest and impact to the image taken from a lower angle like right above the crib sheet rather than the standard ''adult'' perspective.', '2006-05-27 00:06:07.000000', NULL, 1),
(2461294, 337068, 58906, '<td valign="top">I really like this image.  Great contrast, colors, lines and especially the perspective giving depth and 3 dimensional effect.</td>', 'I really like this image.  Great contrast, colors, lines and especially the perspective giving depth and 3 dimensional effect.', '2006-05-27 00:11:12.000000', NULL, 1),
(2461308, 338238, 58906, '<td valign="top">I have seen them get passed in the final meters on the outside though.  Nice colors, and lines.  A slower shutter speed may have added interest and impact with some motion blur to the legs and feet on the pedals.</td>', 'I have seen them get passed in the final meters on the outside though.  Nice colors, and lines.  A slower shutter speed may have added interest and impact with some motion blur to the legs and feet on the pedals.', '2006-05-27 00:18:45.000000', NULL, 1),
(2461316, 336879, 58906, '<td valign="top">Well done!  Great perspective, lighting and sharpness.</td>', 'Well done!  Great perspective, lighting and sharpness.', '2006-05-27 00:22:20.000000', NULL, 1),
