INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2477731, 338169, 22734, '<td valign="top">A soothing and beautiful wall hanger. Congratulations on your top 20 finish.</td>', 'A soothing and beautiful wall hanger. Congratulations on your top 20 finish.', '2006-06-02 00:07:28.000000', NULL, 0),
(2477768, 336011, 24454, '<td valign="top">Wow!  This is awesome!  What an amazing feel this photo has.  I really like your other work too.   Your blue picture is really striking!!!<br/> <br/></td>', 'Wow!  This is awesome!  What an amazing feel this photo has.  I really like your other work too.   Your blue picture is really striking!!! ', '2006-06-02 00:17:14.000000', NULL, 0),
(2477770, 338129, 36065, '<td valign="top"><b>--Trading Post Comment--</b> <br/> <br/>Congrats on one more goal crossed off.<br/> <br/><b>Camera Work/Technical:</b> Excellent focus and great coloring.  Excellent settings to catch a crystal clear image with no distracting motion.<br/> <br/><b>Lighting:</b> While it provides a great effect, I think that its a little harsh.  It looks like you lost some detail in her face, as it was a bit overexposed.<br/> <br/><b>Composition/Content:</b> Wonderful in both areas.  Her figure and shadow very well together to move the viewer through the frame.<br/> <br/><b>My Opinion:</b> You met the challenge very well, and you finished with a well-deserved top 10.<br/> <br/>Eric<br/></td>', '--Trading Post Comment--  Congrats on one more goal crossed off. Camera Work/Technical: Excellent focus and great coloring.  Excellent settings to catch a crystal clear image with no distracting motion. Lighting: While it provides a great effect, I think that its a little harsh.  It looks like you lost some detail in her face, as it was a bit overexposed. Composition/Content: Wonderful in both areas.  Her figure and shadow very well together to move the viewer through the frame. My Opinion: You met the challenge very well, and you finished with a well-deserved top 10. Eric', '2006-06-02 00:19:07.000000', NULL, 0),
(2478062, 336912, 40718, '<td valign="top">A) Ignore the 1s and 2s.  Everybody gets a few so it all evens out.  Just troll voting.<br/> <br/>I like the idea.  It''s a nice shot.  The biggest problem, and it isn''t really a problem in reality, is there isn''t a ton of "wow" to the shot.  It is also quite centered which leads to a static composition.  Focus and colors are excellent.  Lighting is well done.  You are on the upper end of the range I comment on and I can easily tell.  There isn''t as much for me to comment on.</td>', 'A) Ignore the 1s and 2s.  Everybody gets a few so it all evens out.  Just troll voting. I like the idea.  It''s a nice shot.  The biggest problem, and it isn''t really a problem in reality, is there isn''t a ton of "wow" to the shot.  It is also quite centered which leads to a static composition.  Focus and colors are excellent.  Lighting is well done.  You are on the upper end of the range I comment on and I can easily tell.  There isn''t as much for me to comment on.', '2006-06-02 01:44:14.000000', NULL, 0),
(2478278, 337931, 52908, '<td valign="top">I wanna get outta debt :(</td>', 'I wanna get outta debt :(', '2006-06-02 03:17:34.000000', NULL, 0),
(2478452, 338054, 5728, '<td valign="top">Congratulations on your ribbon!</td>', 'Congratulations on your ribbon!', '2006-06-02 07:52:39.000000', NULL, 0),
(2478540, 338287, 50034, '<td valign="top">My premise that the Bible is a success in Itself <b>could</b> easily have been based solely on the fact that I believe it, and that it has been the single greatest influence in my life for any possible personal sucess that could be cited.  (This particular copy was printed by A. J. Holman &amp; Co., Philadelphia, 1892.  <i>Family heirloom.</i>)<br/>   However, I chose to take a different approach for the purpose of this challenge.  Any historian will remember that The Bible was the first book created by the "modern" printing press of Gutenberg.  It remains the success that it is because it remains the <b>"most purchased &amp; most unread"</b> book of all time.  (Of course, the "most unread" part lends credibility to a label of <i>Failure</i> from a purely human vantage point.)<br/><br/><i>Message edited by author 2006-06-02 08:19:59.</i></td>', 'My premise that the Bible is a success in Itself could easily have been based solely on the fact that I believe it, and that it has been the single greatest influence in my life for any possible personal sucess that could be cited.  (This particular copy was printed by A. J. Holman & Co., Philadelphia, 1892.  Family heirloom.)   However, I chose to take a different approach for the purpose of this challenge.  Any historian will remember that The Bible was the first book created by the "modern" printing press of Gutenberg.  It remains the success that it is because it remains the "most purchased & most unread" book of all time.  (Of course, the "most unread" part lends credibility to a label of Failure from a purely human vantage point.)', '2006-06-02 09:16:53.000000', '2006-06-02 09:19:59.000000', 0),
(2478920, 338217, 57882, '<td valign="top">This shot may benefit from a tighter crop, but the concept is good.</td>', 'This shot may benefit from a tighter crop, but the concept is good.', '2006-06-02 12:28:05.000000', NULL, 0),
